      real: "Nombre à virgule flottante en simple précision sur 4 octets. FLOAT(p) avec p de 1 à 24 sélectionne ce type.",
      double: "Nombre à virgule flottante en double précision sur 8 octets. FLOAT sans précision en est un alias ; FLOAT(p) avec p de 25 à 53 le sélectionne.",
