      macaddr: "Adresse MAC. MACADDR stocke des adresses de 6 octets et MACADDR8 des adresses de 8 octets.",
      geometry: "Type géométrique bidimensionnel intégré. La géométrie PostgreSQL est planaire et n'a pas de SRID ; utilisez PostGIS pour les coordonnées géographiques, les projections ou les opérations spatiales avancées.",
