    syncSecretNotice: "Par défaut, DBX ne synchronise que les détails des connexions et les paramètres. Les mots de passe de base de données, mots de passe SSH, mots de passe de proxy, jetons de tunnel HTTP, chaînes de connexion et clés d’API IA restent en local.",
