    syncSnippetSecretsPassphrase: "Mot de passe des identifiants synchronisés",
    syncSnippetSecretsPassphraseDescription:
      "Nécessaire uniquement pour inclure ou restaurer des identifiants chiffrés. Il protège les données sensibles telles que les identifiants de base de données. Il est distinct du mot de passe de l’instantané ; vous pouvez saisir le même mot de passe, mais DBX ne le réutilisera pas automatiquement. Les téléversements automatiques n’incluent jamais les identifiants.",
